INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(7758456, 1284361, 66267, '<td valign="top">I was just there a few weeks ago! <br/> <br/>Check out this image of Stalker I took on 4x5 large format film: <br/> <br/>https://www.instagram.com/p/CxqecCNu7YE/</td>', 'I was just there a few weeks ago!  Check out this image of Stalker I took on 4x5 large format film:  https://www.instagram.com/p/CxqecCNu7YE/', '2023-10-04 11:50:36.000000', NULL, 1),
(7758468, 1284260, 42733, '<td valign="top">My favorite in this challenge.</td>', 'My favorite in this challenge.', '2023-10-04 16:44:55.000000', NULL, 1),
(7758469, 1284314, 42733, '<td valign="top">My pick for red in this challenge.</td>', 'My pick for red in this challenge.', '2023-10-04 16:45:05.000000', NULL, 1),
(7758470, 1284367, 42733, '<td valign="top">My pick for yellow in this challenge.</td>', 'My pick for yellow in this challenge.', '2023-10-04 16:45:15.000000', NULL, 1),
(7758579, 1284372, 77196, '<td valign="top">Nice feeling of depth to photo.</td>', 'Nice feeling of depth to photo.', '2023-10-07 11:39:02.000000', NULL, 1),
(7758580, 1284363, 77196, '<td valign="top">Beautiful horse. Nice L/R balance between horse and hill above the top rail of fence.</td>', 'Beautiful horse. Nice L/R balance between horse and hill above the top rail of fence.', '2023-10-07 11:40:00.000000', NULL, 1),
(7758581, 1284374, 77196, '<td valign="top">Nice sense of depth to photo. Love the detail you were able to bring out in the mountains, and the pop of color with the barn. The dip in the far line of the harvested area in the center of the photo seems to add interest. Only nit-pick is the tree in front of the white door on the barn.</td>', 'Nice sense of depth to photo. Love the detail you were able to bring out in the mountains, and the pop of color with the barn. The dip in the far line of the harvested area in the center of the photo seems to add interest. Only nit-pick is the tree in front of the white door on the barn.', '2023-10-07 11:43:07.000000', NULL, 1),
(7758582, 1284368, 77196, '<td valign="top">Nicely shot. Nice feel of motion to the water.</td>', 'Nicely shot. Nice feel of motion to the water.', '2023-10-07 11:44:51.000000', NULL, 1),
(7758585, 1284316, 77196, '<td valign="top">Precious picture. Great models. Nice composition. I might have tried to lighten a bit so the lighting on the boy &amp; horse was brighter and not blend so much with the shadows.</td>', 'Precious picture. Great models. Nice composition. I might have tried to lighten a bit so the lighting on the boy & horse was brighter and not blend so much with the shadows.', '2023-10-07 11:48:25.000000', NULL, 1),
(7758586, 1284209, 77196, '<td valign="top">Pleasing picture. It takes in a lot of elements, and might work better with a primary subject.</td>', 'Pleasing picture. It takes in a lot of elements, and might work better with a primary subject.', '2023-10-07 11:51:21.000000', NULL, 1),
(7758587, 1284243, 77196, '<td valign="top">(The horse says...) Who, me? Beautiful spot. Love the farmhouse, and your use of the tree / pasture to frame the horse. This almost feels like two pictures - one of the horse / tree / farmhouse / pasture, and one of the red barn / sky / pasture. Your location doesn''t allow the elements to be united in a single scene. The result is that the horse doesn''t appear to have enough room in front of it, and the eye is drawn to the empty pasture between the horse and red barn.</td>', '(The horse says...) Who, me? Beautiful spot. Love the farmhouse, and your use of the tree / pasture to frame the horse. This almost feels like two pictures - one of the horse / tree / farmhouse / pasture, and one of the red barn / sky / pasture. Your location doesn''t allow the elements to be united in a single scene. The result is that the horse doesn''t appear to have enough room in front of it, and the eye is drawn to the empty pasture between the horse and red barn.', '2023-10-07 11:56:57.000000', NULL, 1),
(7758588, 1284260, 77196, '<td valign="top">Absolutely wonderful light! The balloon is glowing! Nice sense of depth to the image.</td>', 'Absolutely wonderful light! The balloon is glowing! Nice sense of depth to the image.', '2023-10-07 11:58:10.000000', NULL, 1),
(7758589, 1284361, 77196, '<td valign="top">I love castles! Your composition makes the castle seem even more remote and deserted.</td>', 'I love castles! Your composition makes the castle seem even more remote and deserted.', '2023-10-07 11:59:40.000000', NULL, 1),
(7758590, 1284371, 77196, '<td valign="top">I like the feeling of depth in the picture. To me, the school bus is a distraction, drawing the eye away from the main scene. The image looks like it was a bit hazy when you took it, but the haze serves no apparent purpose.</td>', 'I like the feeling of depth in the picture. To me, the school bus is a distraction, drawing the eye away from the main scene. The image looks like it was a bit hazy when you took it, but the haze serves no apparent purpose.', '2023-10-07 12:03:47.000000', NULL, 1),
(7758591, 1284120, 77196, '<td valign="top">Take me home country roads... Nice sense of depth to picture. Not sure about the shadow in the mid-ground (cloud shadow?).</td>', 'Take me home country roads... Nice sense of depth to picture. Not sure about the shadow in the mid-ground (cloud shadow?).', '2023-10-07 12:05:09.000000', NULL, 1),
(7758592, 1284365, 77196, '<td valign="top">Very creative shot. I think the angle of the light adds to the image.</td>', 'Very creative shot. I think the angle of the light adds to the image.', '2023-10-07 12:06:02.000000', NULL, 1),
(7758593, 1284370, 77196, '<td valign="top">Interesting trees. Nice lighting on the flowers.</td>', 'Interesting trees. Nice lighting on the flowers.', '2023-10-07 12:06:53.000000', NULL, 1),
(7758594, 1284373, 77196, '<td valign="top">Nice DOF and blurred background.</td>', 'Nice DOF and blurred background.', '2023-10-07 12:08:12.000000', NULL, 1),
(7758595, 1284345, 77196, '<td valign="top">My mind sees trees, grass, no main subject. Looks like it might be a bit over sharpened.</td>', 'My mind sees trees, grass, no main subject. Looks like it might be a bit over sharpened.', '2023-10-07 12:09:36.000000', NULL, 1),
(7758596, 1284366, 77196, '<td valign="top">Beautiful lighting! Nice sense of depth. Love the detail on the mountain. I find the shadow across the foreground distracting, but not much you can do about that!</td>', 'Beautiful lighting! Nice sense of depth. Love the detail on the mountain. I find the shadow across the foreground distracting, but not much you can do about that!', '2023-10-07 12:12:23.000000', NULL, 1),
(7758597, 1284355, 77196, '<td valign="top">I like the path bending away, out of sight. I''d suggest lightening the image to make the dog''s face visible - it has a mostly black face in near-shadow, and you can''t see its eyes.</td>', 'I like the path bending away, out of sight. I''d suggest lightening the image to make the dog''s face visible - it has a mostly black face in near-shadow, and you can''t see its eyes.', '2023-10-07 12:14:29.000000', NULL, 1),
(7758598, 1284367, 77196, '<td valign="top">Very nicely done. Beautiful colors, sky.</td>', 'Very nicely done. Beautiful colors, sky.', '2023-10-07 12:15:09.000000', NULL, 1),
(7758599, 1284263, 77196, '<td valign="top">Nice scene. Good lighting on cow''s face.</td>', 'Nice scene. Good lighting on cow''s face.', '2023-10-07 12:16:18.000000', NULL, 1),
(7758600, 1284350, 77196, '<td valign="top">Stunning! This image speaks on the emotional level more than on the visual level.</td>', 'Stunning! This image speaks on the emotional level more than on the visual level.', '2023-10-07 12:17:36.000000', NULL, 1),
(7758601, 1284339, 77196, '<td valign="top">Things I really like: Mist on the lake, lighting and color of leaves, position of land, misty background, nothing to distract from island, lake, and trees!</td>', 'Things I really like: Mist on the lake, lighting and color of leaves, position of land, misty background, nothing to distract from island, lake, and trees!', '2023-10-07 12:19:14.000000', NULL, 1),
(7758602, 1284338, 77196, '<td valign="top">Nicely balanced image. Comes across as a bit on the gloomy side.</td>', 'Nicely balanced image. Comes across as a bit on the gloomy side.', '2023-10-07 12:20:23.000000', NULL, 1),
(7758603, 1284337, 77196, '<td valign="top">Nice color against the grey sky. Do you hate power lines as much as I do?</td>', 'Nice color against the grey sky. Do you hate power lines as much as I do?', '2023-10-07 12:21:28.000000', NULL, 1),
