(7758606, 1284369, 77196, '<td valign="top">Makes me want to visit!</td>', 'Makes me want to visit!', '2023-10-07 12:24:03.000000', NULL, 1),
(7758607, 1284362, 77196, '<td valign="top">Great scene. Golden light.</td>', 'Great scene. Golden light.', '2023-10-07 12:25:10.000000', NULL, 1),
