(7758672, 1284339, 38162, '<td valign="top">Great capture.  Tonality sets a calm mood. Spent many summers at Horn Lake. Love the area.</td>', 'Great capture.  Tonality sets a calm mood. Spent many summers at Horn Lake. Love the area.', '2023-10-08 12:54:21.000000', NULL, 1),
(7758735, 1284339, 30049, '<td valign="top">I like the pop of color.  A bit too much negative space (sky) I think.  Could be a cool pano type crop?</td>', 'I like the pop of color.  A bit too much negative space (sky) I think.  Could be a cool pano type crop?', '2023-10-09 18:20:52.000000', NULL, 1),
(7758736, 1284374, 30049, '<td valign="top">Beautiful colors and a wonderful scene. Feels a little soft.  A tight crop that lost some detail maybe?</td>', 'Beautiful colors and a wonderful scene. Feels a little soft.  A tight crop that lost some detail maybe?', '2023-10-09 18:22:44.000000', NULL, 1),
(7758737, 1284371, 30049, '<td valign="top">Nice view!  Did you try a levels adjustment on this?  Would really make it pop.</td>', 'Nice view!  Did you try a levels adjustment on this?  Would really make it pop.', '2023-10-09 18:23:50.000000', NULL, 1),
