(7758789, 1284374, 50695, '<td valign="top">love the painted-on primary colors. it feels good.</td>', 'love the painted-on primary colors. it feels good.', '2023-10-11 11:00:35.000000', NULL, 0),
(7758790, 1284365, 50695, '<td valign="top">i definitely would have given this a 10. the dpc voters are not going to understand just how great this composition is. but it is impressive you got over a 6 in a landscape challenge with this much foreground.</td>', 'i definitely would have given this a 10. the dpc voters are not going to understand just how great this composition is. but it is impressive you got over a 6 in a landscape challenge with this much foreground.', '2023-10-11 11:02:15.000000', NULL, 0),
(7758791, 1284368, 50695, '<td valign="top">it really is an intriguing image. well done.</td>', 'it really is an intriguing image. well done.', '2023-10-11 11:04:37.000000', NULL, 0),
(7758793, 1284362, 141319, '<td valign="top">Thank you Ammie - I was in the Drakensberg on a conference and managed to "click" this on the first evening. I went back to the same area almost every evening for 4 days, but never found the old lady and her goats again. I would have loved to improve on this :-) - as they say: capture the moment.</td>', 'Thank you Ammie - I was in the Drakensberg on a conference and managed to "click" this on the first evening. I went back to the same area almost every evening for 4 days, but never found the old lady and her goats again. I would have loved to improve on this :-) - as they say: capture the moment.', '2023-10-11 13:42:03.000000', NULL, 0),
(7758800, 1284260, 42013, '<td valign="top">Congrats Robert! Very striking image</td>', 'Congrats Robert! Very striking image', '2023-10-11 17:35:56.000000', NULL, 0),
